//! Trigger-order and `updateLeverage` signing vectors generated by the official Python SDK
//! (`tests/trigger_vectors.json`, from `tests/gen_trigger_vectors.py`). Never regenerate them to make a
//! change pass.
//!
//! `serde_json::Value` equality ignores key order, so the action JSON check alone does not prove the
//! msgpack layout: the connection id and signature checks do.

use roshar_hyperliquid::Signer;
use roshar_hyperliquid::{Action, Cloid, Grouping, OrderType, Tif, Tpsl, TypedOrderReq};
use serde_json::Value;

fn load() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/trigger_vectors.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn cloid(s: &str) -> Cloid {
    hex::decode(s.trim_start_matches("0x"))
        .unwrap()
        .try_into()
        .unwrap()
}

fn num(v: &Value) -> f64 {
    v.as_str().unwrap().parse().unwrap()
}

fn order(o: &Value) -> TypedOrderReq {
    let t = &o["t"];
    let order_type = if let Some(l) = t.get("limit") {
        OrderType::Limit(match l["tif"].as_str().unwrap() {
            "Alo" => Tif::Alo,
            "Ioc" => Tif::Ioc,
            "Gtc" => Tif::Gtc,
            x => panic!("tif {x}"),
        })
    } else {
        let tr = &t["trigger"];
        OrderType::Trigger {
            is_market: tr["isMarket"].as_bool().unwrap(),
            trigger_px: num(&tr["triggerPx"]),
            tpsl: match tr["tpsl"].as_str().unwrap() {
                "tp" => Tpsl::Tp,
                "sl" => Tpsl::Sl,
                x => panic!("tpsl {x}"),
            },
        }
    };
    TypedOrderReq {
        asset: o["a"].as_u64().unwrap() as u32,
        is_buy: o["b"].as_bool().unwrap(),
        px: num(&o["p"]),
        sz: num(&o["s"]),
        reduce_only: o["r"].as_bool().unwrap(),
        order_type,
        cloid: o.get("c").map(|c| cloid(c.as_str().unwrap())),
    }
}

fn action(a: &Value) -> Action {
    match a["type"].as_str().unwrap() {
        "order" => Action::OrderTyped {
            orders: a["orders"].as_array().unwrap().iter().map(order).collect(),
            grouping: match a["grouping"].as_str().unwrap() {
                "na" => Grouping::Na,
                "normalTpsl" => Grouping::NormalTpsl,
                "positionTpsl" => Grouping::PositionTpsl,
                g => panic!("grouping {g}"),
            },
        },
        "updateLeverage" => Action::UpdateLeverage {
            asset: a["asset"].as_u64().unwrap() as u32,
            is_cross: a["isCross"].as_bool().unwrap(),
            leverage: a["leverage"].as_u64().unwrap() as u32,
        },
        t => panic!("type {t}"),
    }
}

/// Hex big-endian integer, compared without leading zeros.
fn int_hex(s: &str) -> String {
    let t = s
        .trim_start_matches("0x")
        .trim_start_matches('0')
        .to_ascii_lowercase();
    if t.is_empty() {
        "0".into()
    } else {
        t
    }
}

#[test]
fn sdk_trigger_vectors() {
    let v = load();
    let key = v["key"].as_str().unwrap();
    let cases = v["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 24);
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let mainnet = c["mainnet"].as_bool().unwrap();
        let signer = Signer::from_hex(key, c["vault"].as_str(), mainnet).unwrap();
        let act = action(&c["action"]);
        let nonce = c["nonce"].as_u64().unwrap();

        assert_eq!(
            Signer::action_json(&act),
            c["action"],
            "{name}: action json"
        );
        let cid = signer.connection_id(&act, nonce).unwrap();
        assert_eq!(
            format!("0x{}", hex::encode(cid)),
            c["connection_id"].as_str().unwrap(),
            "{name}: connection id"
        );

        let p = signer.sign(&act, nonce).unwrap();
        let (sig, want) = (&p["signature"], &c["signature"]);
        assert_eq!(
            int_hex(sig["r"].as_str().unwrap()),
            int_hex(want["r"].as_str().unwrap()),
            "{name}: r"
        );
        assert_eq!(
            int_hex(sig["s"].as_str().unwrap()),
            int_hex(want["s"].as_str().unwrap()),
            "{name}: s"
        );
        assert_eq!(sig["v"], want["v"], "{name}: v");
        assert_eq!(p["action"], c["action"], "{name}: payload action");
        assert_eq!(p["nonce"].as_u64(), Some(nonce));
        assert_eq!(p["vaultAddress"], c["vault"], "{name}: vaultAddress");
    }
}

/// A limit-only `OrderTyped` with grouping na hashes exactly like the existing `Order` with no priority.
#[test]
fn typed_limit_matches_order() {
    let signer = Signer::from_hex(load()["key"].as_str().unwrap(), None, true).unwrap();
    let old = Action::Order {
        orders: vec![roshar_hyperliquid::OrderReq {
            asset: 3,
            is_buy: true,
            px: 1.2345,
            sz: 10.0,
            reduce_only: false,
            tif: Tif::Alo,
            cloid: Some([7u8; 16]),
        }],
        priority: None,
    };
    let new = Action::OrderTyped {
        orders: vec![TypedOrderReq {
            asset: 3,
            is_buy: true,
            px: 1.2345,
            sz: 10.0,
            reduce_only: false,
            order_type: OrderType::Limit(Tif::Alo),
            cloid: Some([7u8; 16]),
        }],
        grouping: Grouping::Na,
    };
    assert_eq!(
        signer.connection_id(&old, 42).unwrap(),
        signer.connection_id(&new, 42).unwrap()
    );
    assert_eq!(Signer::action_json(&old), Signer::action_json(&new));
}
